export interface ConnectorConfig {
  salesforceAccessToken: string
  salesforceInstance: string
  hubspotAccessToken: string
  hubspotBaseUrl?: string
  fetch?: typeof fetch
}

export interface HubSpotDealWebhookPayload {
  subscriptionType: string
  propertyName: string
  objectId: string
  propertyValue: string
  eventId: string
  occurredAt: number
  portalId: string
  appId: string
}

export interface HubSpotDealResponse {
  id: string
  properties: {
    dealname?: string
    website?: string
    dealstage?: string
  }
}

export interface SalesforceUpsertResponse {
  id: string
  success: boolean
  errors: unknown[]
  created: boolean
}

export interface ConnectorResult {
  salesforceAccountId: string
  created: boolean
  dealId: string
}

async function fetchHubSpotDeal(
  dealId: string,
  config: ConnectorConfig
): Promise<HubSpotDealResponse> {
  const baseUrl = config.hubspotBaseUrl ?? 'https://api.hubapi.com'
  const url = `${baseUrl}/crm/v3/objects/deals/${dealId}?properties=dealname,website,dealstage`
  const fetchFn = config.fetch ?? fetch
  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.hubspotAccessToken}`,
      Accept: 'application/json',
    },
  })
  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for GET ${url}`)
  }
  return (await response.json()) as HubSpotDealResponse
}

async function upsertSalesforceAccount(
  website: string,
  name: string,
  stageName: string | undefined,
  config: ConnectorConfig
): Promise<SalesforceUpsertResponse> {
  const encodedWebsite = encodeURIComponent(website)
  const url = `https://${config.salesforceInstance}.salesforce.com/services/data/v68.0/sobjects/Account/Website__c/${encodedWebsite}`
  const body: {
    Name: name,
    Website: website,
    ...(stageName ? { StageName: stageName } : {}),
  },
  const fetchFn = config.fetch ?? fetch
  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.salesforceAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })
  if (response.status !== 200 && response.status !== 201) {
    throw new Error(`Salesforce upsert error: ${response.status} ${response.statusText} for PATCH ${url}`)
  }
  if (response.status === 204) {
    return { id: '', success: true, errors: [], created: false }
  }
  return (await response.json()) as SalesforceUpsertResponse
}

export async function handle(
  payload: HubSpotDealWebhookPayload,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  if (!payload.objectId) {
    throw new Error('Missing required field: objectId (deal ID)')
  }
  if (!config.salesforceAccessToken) {
    throw new Error('Missing required config: salesforceAccessToken')
  }
  if (!config.salesforceInstance) {
    throw new Error('Missing required config: salesforceInstance')
  }
  if (!config.hubspotAccessToken) {
    throw new Error('Missing required config: hubspotAccessToken')
  }

  const deal = await fetchHubSpotDeal(payload.objectId, config)

  if (!deal.properties.website) {
    throw new Error(`Deal ${payload.objectId} has no website property; cannot upsert Account without external ID`)
  }

  const sfResponse = await upsertSalesforceAccount(
    deal.properties.website,
    deal.properties.dealname ?? payload.propertyValue,
    deal.properties.dealstage,
    config
  )

  return {
    salesforceAccountId: sfResponse.id,
    created: sfResponse.created,
    dealId: payload.objectId,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, HubSpotDealWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

const VALID_CONFIG: ConnectorConfig = {
  salesforceAccessToken: 'test-sf-token',
  salesforceInstance: 'mycompany',
  hubspotAccessToken: 'test-hs-token',
  hubspotBaseUrl: 'https://api.hubapi.com',
}

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/12345')) {
        return jsonResponse({
          id: '12345',
          properties: {
            dealname: 'Acme Corp Deal',
            website: 'acme.com',
            dealstage: 'proposal',
          },
        })
      }
      const endpoint = TARGET_ENDPOINTS.find(
        (e) => e.method === req.method && req.url.includes(e.url.replace('{instance}.', 'mycompany.').replace('{website}', 'acme.com'))
      )
      if (endpoint) return jsonResponse(endpoint.response)
      throw new Error(`Unexpected request: ${req.method} ${req.url}`)
    })
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, { ...VALID_CONFIG, fetch })
    expect(calls.length).toBeGreaterThan(0)
    expect(result.salesforceAccountId).toBe('001xx000003DGhpAAG')
    expect(result.created).toBe(false)
    expect(result.dealId).toBe('12345')
  })
})

describe('handle', () => {
  it('happy path: fetches deal and upserts account', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/12345')) {
        return jsonResponse({
          id: '12345',
          properties: { dealname: 'Acme Corp Deal', website: 'acme.com', dealstage: 'proposal' },
        })
      }
      if (req.url.includes('/sobjects/Account/Website__c/acme.com') && req.method === 'PATCH') {
        expect(req.json).toEqual({ Name: 'Acme Corp Deal', Website: 'acme.com', StageName: 'proposal' })
        expect(req.headers.get('authorization')).toBe('Bearer test-sf-token')
        return jsonResponse({ id: '001xx000003DGhpAAG', success: true, errors: [], created: false }, 200)
      }
      throw new Error(`Unexpected request: ${req.method} ${req.url}`)
    })
    const payload: HubSpotDealWebhookPayload = {
      ...SOURCE_EXAMPLE,
      objectId: '12345',
    }
    const result = await handle(payload, { ...VALID_CONFIG, fetch })
    expect(result).toEqual({ salesforceAccountId: '001xx000003DGhpAAG', created: false, dealId: '12345' })
    expect(calls.length).toBe(2)
  })

  it('creates new account when upsert returns 201', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/999')) {
        return jsonResponse({ id: '999', properties: { dealname: 'New Deal', website: 'new.com' } })
      }
      if (req.url.includes('/sobjects/Account/Website__c/new.com') && req.method === 'PATCH') {
        return jsonResponse({ id: '001NEW000000000000', success: true, errors: [], created: true }, 201)
      }
      throw new Error(`Unexpected request: ${req.method} ${req.url}`)
    })
    const payload: HubSpotDealWebhookPayload = { ...SOURCE_EXAMPLE, objectId: '999', propertyName: 'dealname', propertyValue: 'New Deal' }
    const result = await handle(payload, { ...VALID_CONFIG, fetch })
    expect(result.created).toBe(true)
    expect(result.salesforceAccountId).toBe('001NEW000000000000')
    expect(calls.length).toBe(2)
  })

  it('throws when objectId is missing', async () => {
    const { fetch } = fakeFetch(() => { throw new Error('should not be called') })
    const payload = { ...SOURCE_EXAMPLE, objectId: '' }
    await expect(handle(payload as HubSpotDealWebhookPayload, { ...VALID_CONFIG, fetch })).rejects.toThrow('Missing required field: objectId')
  })

  it('throws when salesforceAccessToken is missing', async () => {
    const { fetch } = fakeFetch(() => { throw new Error('should not be called') })
    const config = { ...VALID_CONFIG, salesforceAccessToken: '' }
    await expect(handle(SOURCE_EXAMPLE as HubSpotDealWebhookPayload, config)).rejects.toThrow('Missing required config: salesforceAccessToken')
  })

  it('throws when salesforceInstance is missing', async () => {
    const { fetch } = fakeFetch(() => { throw new Error('should not be called') })
    const config = { ...VALID_CONFIG, salesforceInstance: '' }
    await expect(handle(SOURCE_EXAMPLE as HubSpotDealWebhookPayload, config)).rejects.toThrow('Missing required config: salesforceInstance')
  })

  it('throws when hubspotAccessToken is missing', async () => {
    const { fetch } = fakeFetch(() => { throw new Error('should not be called') })
    const config = { ...VALID_CONFIG, hubspotAccessToken: '' }
    await expect(handle(SOURCE_EXAMPLE as HubSpotDealWebhookPayload, config)).rejects.toThrow('Missing required config: hubspotAccessToken')
  })

  it('throws when HubSpot API returns error', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/12345')) {
        return jsonResponse({ error: 'Not Found' }, 404)
      }
      throw new Error('unexpected')
    })
    await expect(handle(SOURCE_EXAMPLE as HubSpotDealWebhookPayload, { ...VALID_CONFIG, fetch })).rejects.toThrow('HubSpot API error: 404 Not Found')
  })

  it('throws when deal has no website property', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/12345')) {
        return jsonResponse({ id: '12345', properties: { dealname: 'No Website Deal' } })
      }
      throw new Error('unexpected')
    })
    await expect(handle(SOURCE_EXAMPLE as HubSpotDealWebhookPayload, { ...VALID_CONFIG, fetch })).rejects.toThrow('has no website property')
  })

  it('throws when Salesforce upsert returns non-2xx', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/12345')) {
        return jsonResponse({ id: '12345', properties: { dealname: 'Test', website: 'test.com' } })
      }
      if (req.url.includes('/sobjects/Account/Website__c/test.com')) {
        return jsonResponse({ error: 'Unauthorized' }, 401)
      }
      throw new Error('unexpected')
    })
    await expect(handle(SOURCE_EXAMPLE as HubSpotDealWebhookPayload, { ...VALID_CONFIG, fetch })).rejects.toThrow('Salesforce upsert error: 401 Unauthorized')
  })

  it('handles Salesforce 300 multiple matches error', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/12345')) {
        return jsonResponse({ id: '12345', properties: { dealname: 'Test', website: 'dup.com' } })
      }
      if (req.url.includes('/sobjects/Account/Website__c/dup.com')) {
        return jsonResponse({ error: 'Multiple matches found' }, 300)
      }
      throw new Error('unexpected')
    })
    await expect(handle(SOURCE_EXAMPLE as HubSpotDealWebhookPayload, { ...VALID_CONFIG, fetch })).rejects.toThrow('Salesforce upsert error: 300')
  })

  it('uses dealname from HubSpot deal when available, falls back to propertyValue', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/12345')) {
        return jsonResponse({ id: '12345', properties: { dealname: 'Deal Name From Deal', website: 'fallback.com' } })
      }
      if (req.url.includes('/sobjects/Account/Website__c/fallback.com')) {
        expect(req.json).toEqual({ Name: 'Deal Name From Deal', Website: 'fallback.com' })
        return jsonResponse({ id: '001FB000000000000', success: true, errors: [], created: false }, 200)
      }
      throw new Error('unexpected')
    })
    const payload: HubSpotDealWebhookPayload = { ...SOURCE_EXAMPLE, propertyValue: 'Webhook Property Value' }
    await handle(payload, { ...VALID_CONFIG, fetch })
    expect(calls[1].json).toEqual({ Name: 'Deal Name From Deal', Website: 'fallback.com' })
  })

  it('omits StageName when dealstage is not present', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/crm/v3/objects/deals/12345')) {
        return jsonResponse({ id: '12345', properties: { dealname: 'No Stage', website: 'nostage.com' } })
      }
      if (req.url.includes('/sobjects/Account/Website__c/nostage.com')) {
        expect(req.json).not.toHaveProperty('StageName')
        return jsonResponse({ id: '001NS000000000000', success: true, errors: [], created: false }, 200)
      }
      throw new Error('unexpected')
    })
    await handle({ ...SOURCE_EXAMPLE, objectId: '12345' }, { ...VALID_CONFIG, fetch })
    expect(calls[1].json).not.toHaveProperty('StageName')
  })

  it('uses custom hubspotBaseUrl when provided', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://custom.hubspot.com/crm/v3/objects/deals/12345?properties=dealname,website,dealstage') {
        return jsonResponse({ id: '12345', properties: { dealname: 'Custom', website: 'custom.com' } })
      }
      if (req.url.includes('/sobjects/Account/Website__c/custom.com')) {
        return jsonResponse({ id: '001CU000000000000', success: true, errors: [], created: false }, 200)
      }
      throw new Error(`Unexpected: ${req.url}`)
    })
    const config = { ...VALID_CONFIG, hubspotBaseUrl: 'https://custom.hubspot.com' }
    await handle({ ...SOURCE_EXAMPLE, objectId: '12345' }, { ...config, fetch })
    expect(calls[0].url).toBe('https://custom.hubspot.com/crm/v3/objects/deals/12345?properties=dealname,website,dealstage')
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://developers.hubspot.com/docs/api-reference/latest/webhooks/guide
// Source: https://developer.salesforce.com/docs/platform/api-rest/guide/dome-upsert.html

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "subscriptionType": "deal.propertyChange",
  "propertyName": "dealname",
  "objectId": "12345",
  "propertyValue": "Acme Corp Deal",
  "eventId": "abc-123-def",
  "occurredAt": 1717020000000,
  "portalId": "62515",
  "appId": "273842"
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "PATCH",
    "url": "https://{instance}.salesforce.com/services/data/v68.0/sobjects/Account/Website__c/{website}",
    "response": {
      "id": "001xx000003DGhpAAG",
      "success": true,
      "errors": [],
      "created": false
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

